#include "lexer.hpp"
#include <cctype>
#include <stdexcept>
namespace xe {
Lexer::Lexer(std::string_view input) : source(input) {}
char Lexer::peek(std::size_t n) const { return pos + n < source.size() ? source[pos + n] : '\0'; }
char Lexer::take() { char c=peek(); if(c){++pos;if(c=='\n'){++line;column=1;}else ++column;}return c; }
void Lexer::emit(std::vector<Token>& out,TokenType type,std::string text,int l,int c){out.push_back({type,std::move(text),l,c});}
std::string Lexer::readAsm(int l,int c){while(peek()==' '||peek()=='\t'||peek()=='\r'||peek()=='\n')take();if(peek()!='{')throw std::runtime_error("line "+std::to_string(l)+", column "+std::to_string(c)+": expected '{' after asm");take();std::string raw;int depth=1;char quote=0;while(peek()&&depth){char ch=take();if(quote){raw+=ch;if(ch=='\\'&&peek())raw+=take();else if(ch==quote)quote=0;continue;}if(ch=='\''||ch=='"'){quote=ch;raw+=ch;continue;}if(ch=='{'){++depth;raw+=ch;continue;}if(ch=='}'){if(--depth)raw+=ch;continue;}if(ch=='/'&&peek()=='/'){while(peek()&&peek()!='\n')take();continue;}raw+=ch;}if(depth)throw std::runtime_error("line "+std::to_string(l)+", column "+std::to_string(c)+": unterminated asm block");return raw;}
std::vector<Token> Lexer::scan(){std::vector<Token> out;while(peek()){char c=peek();int l=line,k=column;if(c==' '||c=='\t'||c=='\r'){take();continue;}if(c=='\n'){take();if(!continuation)emit(out,TokenType::Newline,"\\n",l,k);continuation=false;continue;}if(c==';'){take();continuation=true;continue;}if(c=='/'&&peek(1)=='/'){while(peek()&&peek()!='\n')take();continue;}
if(std::isalpha(static_cast<unsigned char>(c))||c=='_'){std::string word;while(std::isalnum(static_cast<unsigned char>(peek()))||peek()=='_')word+=take();if(word=="asm")emit(out,TokenType::RawAsm,readAsm(l,k),l,k);else emit(out,TokenType::Identifier,std::move(word),l,k);continue;}
if(std::isdigit(static_cast<unsigned char>(c))){std::string n;while(std::isdigit(static_cast<unsigned char>(peek())))n+=take();if(peek()=='.'&&std::isdigit(static_cast<unsigned char>(peek(1)))){n+=take();while(std::isdigit(static_cast<unsigned char>(peek())))n+=take();}if(peek()=='e'||peek()=='E'){n+=take();if(peek()=='+'||peek()=='-')n+=take();if(!std::isdigit(static_cast<unsigned char>(peek())))throw std::runtime_error("line "+std::to_string(line)+", column "+std::to_string(column)+": malformed exponent");while(std::isdigit(static_cast<unsigned char>(peek())))n+=take();}emit(out,TokenType::Number,std::move(n),l,k);continue;}
if(c=='"'){take();std::string s;while(peek()&&peek()!='"'){if(peek()=='\\'){take();char e=take();switch(e){case 'n':s+='\n';break;case 't':s+='\t';break;case 'r':s+='\r';break;default:s+=e;}}else s+=take();}if(!peek())throw std::runtime_error("line "+std::to_string(l)+", column "+std::to_string(k)+": unterminated string");take();emit(out,TokenType::String,std::move(s),l,k);continue;}
if((c=='<'&&peek(1)=='<')||(c=='>'&&peek(1)=='>')){take();take();emit(out,c=='<'?TokenType::ShiftLeft:TokenType::ShiftRight,c=='<'?"<<":">>",l,k);continue;}
take();TokenType type;std::string symbol(1,c);switch(c){case ':':if(peek()=='='){symbol+=take();type=TokenType::Assign;}else type=TokenType::Colon;break;case ',':type=TokenType::Comma;break;case '.':type=TokenType::Dot;break;case '(':type=TokenType::LParen;break;case ')':type=TokenType::RParen;break;case '{':type=TokenType::LBrace;break;case '}':type=TokenType::RBrace;break;case '[':type=TokenType::LBracket;break;case ']':type=TokenType::RBracket;break;case '+':type=TokenType::Plus;break;case '-':type=TokenType::Minus;break;case '*':type=TokenType::Star;break;case '/':type=TokenType::Slash;break;case '%':type=TokenType::Percent;break;case '&':if(peek()=='&'){symbol+=take();type=TokenType::AndAnd;}else type=TokenType::Amp;break;case '|':if(peek()=='|'){symbol+=take();type=TokenType::OrOr;}else type=TokenType::BitOr;break;case '^':type=TokenType::BitXor;break;case '~':type=TokenType::BitNot;break;case '@':type=TokenType::At;break;case '#':type=TokenType::Hash;break;case '!':if(peek()=='='){symbol+=take();type=TokenType::NotEqual;}else type=TokenType::Bang;break;case '=':if(peek()=='=')throw std::runtime_error("line "+std::to_string(l)+", column "+std::to_string(k)+": use '=' for equality and ':=' for assignment");type=TokenType::Equal;break;case '<':if(peek()=='='){symbol+=take();type=TokenType::LessEqual;}else type=TokenType::Less;break;case '>':if(peek()=='='){symbol+=take();type=TokenType::GreaterEqual;}else type=TokenType::Greater;break;default:throw std::runtime_error("line "+std::to_string(l)+", column "+std::to_string(k)+": unexpected character");}emit(out,type,std::move(symbol),l,k);
}out.push_back({TokenType::End,"",line,column});return out;}
}
